import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { chmodSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, extname, join } from "node:path";
import { recordedInvocations } from "../src/execute";
import { createFixture, wardLauncher, type Fixture } from "../src/fixture";
import { writeRecordingWrapper } from "../src/live";
import { cleanupOwnedProcesses, run, SYSTEM_PATH } from "../src/process";

// Executes the hook files generated by the real `ward integrate cline --guard-approved-specs`
// against Cline 3.0.72, read from @cline/core@0.0.94 and @cline/shared@0.0.94:
// - Workspace hooks are files in .cline/hooks/ or .clinerules/hooks/ whose name (without a script
//   extension) is an event: PreToolUse, PostToolUse, TaskComplete, ... Other files are ignored.
// - A file without a known extension runs as `bash <file>` in the session cwd, event JSON on stdin.
// - PreToolUse and PostToolUse are awaited; stdout (or its last HOOK_CONTROL line) is control JSON:
//   cancel: true stops the tool with errorMessage; contextModification is appended to the result.
//   Invalid JSON is logged and ignored. TaskComplete runs detached and its output is ignored.
// - Payloads carry hookName, workspaceRoots and preToolUse/postToolUse {toolName, parameters}, where
//   every parameter is a string (objects JSON-serialized). Tools: editor {path}, apply_patch {input},
//   run_commands {commands: [..]}.
// The real Ward answers behind a recording wrapper.

const EVENTS = ["TaskStart", "TaskResume", "TaskCancel", "TaskComplete", "TaskError", "PreToolUse", "PostToolUse", "UserPromptSubmit", "PreCompact", "SessionShutdown"];
const EXTENSIONS = ["", ".sh", ".bash", ".zsh", ".js", ".mjs", ".cjs", ".ts", ".mts", ".cts", ".py", ".ps1"];

/** Lists the hook files Cline discovers in a directory, by event. */
function discovered(dir: string): Record<string, string> {
  const found: Record<string, string> = {};
  for (const name of readdirSync(dir)) {
    const ext = extname(name).toLowerCase();
    if (!EXTENSIONS.includes(ext)) continue;
    const base = name.slice(0, name.length - ext.length).trim().toLowerCase();
    const event = EVENTS.find((e) => e.toLowerCase() === base);
    if (event) found[event] = join(dir, name);
  }
  return found;
}

/** Interprets hook stdout the way @cline/core does. */
function control(stdout: string): { cancel?: boolean; reason?: string; context?: string } | undefined {
  const text = stdout.trim();
  if (!text) return undefined;
  const lines = text.split("\n").map((l) => l.trim()).filter((l) => l.startsWith("HOOK_CONTROL\t")).map((l) => l.slice(13));
  let parsed: any;
  try {
    parsed = JSON.parse(lines.length > 0 ? lines[lines.length - 1] : text);
  } catch {
    return undefined; // logged and ignored
  }
  const context = parsed.context ?? parsed.contextModification;
  return parsed.cancel === true ? { cancel: true, reason: parsed.errorMessage ?? context } : { context: context ?? parsed.errorMessage };
}

let fixture: Fixture;
let unguarded: Fixture;
let hooks: Record<string, string>;
let log: string;
let bin: string;

beforeAll(async () => {
  const ward = wardLauncher(process.env)!;
  fixture = await createFixture({ harness: "cline", guard: true, ward });
  unguarded = await createFixture({ harness: "cline", guard: false, ward });
  hooks = discovered(join(fixture.root, ".cline/hooks"));
  bin = join(dirname(fixture.root), "ward-bin");
  log = join(dirname(fixture.root), "ward-log");
  writeRecordingWrapper(bin, log, ward);
  mkdirSync(join(fixture.root, "src/main/java"), { recursive: true });
  mkdirSync(join(fixture.root, "openspec/specs/auth"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/specs/auth/spec.md"), "# Auth\n");
  mkdirSync(join(fixture.root, "openspec/changes/add-x"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/changes/add-x/tasks.md"), "- [ ] 1.1\n");
  writeFileSync(join(fixture.root, "openspec-stub.sh"), "#!/bin/sh\nexit 0\n");
  chmodSync(join(fixture.root, "openspec-stub.sh"), 0o755);
});

afterAll(() => {
  fixture?.cleanup();
  unguarded?.cleanup();
  cleanupOwnedProcesses();
});

/** Runs a hook file like Cline: `bash <file>` in the session cwd, event JSON on stdin. */
async function launch(file: string, f: Fixture, payload: unknown, cwd = f.root) {
  const before = recordedInvocations(log).length;
  const stdin = typeof payload === "string" ? payload : JSON.stringify(payload);
  const result = await run(["/bin/bash", file], { cwd, env: { ...f.env, PATH: `${bin}:${SYSTEM_PATH}` }, stdin, timeoutMs: 60_000 });
  return { result, control: control(result.stdout), invocations: recordedInvocations(log).slice(before) };
}

const base = (f: Fixture, hookName: string) => ({ clineVersion: "3.0.72", hookName, timestamp: "2026-10-16T00:00:00Z", taskId: "t", workspaceRoots: [f.root], userId: "u" });
const pre = (toolName: string, input: Record<string, unknown>, cwd?: string) =>
  launch(hooks.PreToolUse, fixture, {
    ...base(fixture, "tool_call"),
    tool_call: { id: "1", name: toolName, input },
    preToolUse: { toolName, parameters: Object.fromEntries(Object.entries(input).map(([k, v]) => [k, typeof v === "string" ? v : JSON.stringify(v)])) },
  }, cwd);
const post = (toolName: string, input: Record<string, string>) =>
  launch(hooks.PostToolUse, fixture, {
    ...base(fixture, "tool_result"),
    postToolUse: { toolName, parameters: input, result: "ok", success: true, executionTimeMs: 1 },
  });

describe("generated hook files against Cline 3.0.72", () => {
  test("Cline discovers the guard and check as PreToolUse and PostToolUse hooks", () => {
    expect(Object.keys(hooks).sort()).toEqual(["PostToolUse", "PreToolUse"]);
  });

  test("negative control: the legacy ward.json and ward.sh are not hook files", () => {
    const dir = join(fixture.root, "legacy-hooks");
    mkdirSync(dir);
    writeFileSync(join(dir, "ward.json"), "{}");
    writeFileSync(join(dir, "ward.sh"), "#!/bin/sh\n");
    expect(discovered(dir)).toEqual({});
  });

  test("both files carry the ownership marker", () => {
    for (const file of Object.values(hooks)) expect(readFileSync(file, "utf8")).toContain("ward-owned: cline-native-hooks v1");
  });
});

describe("hook execution", () => {
  test("the guard cancels an edit to an approved spec, from a subdirectory session", async () => {
    const { control, invocations } = await pre("editor", { path: join(fixture.root, "openspec/specs/auth/spec.md"), new_text: "x" }, join(fixture.root, "src/main/java"));
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "cline", "--guard-approved-specs", "--event-stdin"]]);
    expect(invocations[0].cwd.endsWith("/project")).toBe(true);
    expect(control?.cancel).toBe(true);
    expect(control?.reason).toContain("openspec/specs/auth/spec.md");
  });

  test("the guard reads every command of a run_commands call", async () => {
    const denied = await pre("run_commands", { commands: ["ls", "rm openspec/specs/auth/spec.md"] });
    expect(denied.control?.cancel).toBe(true);
    const allowed = await pre("run_commands", { commands: ["ls src"] });
    expect(allowed.control).toBeUndefined();
  });

  test("the guard allows a patch to an active change", async () => {
    const { control } = await pre("apply_patch", { input: "*** Begin Patch\n*** Update File: openspec/changes/add-x/tasks.md\n@@\n-- [ ] 1.1\n+- [x] 1.1\n*** End Patch\n" });
    expect(control).toBeUndefined();
  });

  test("tools that change nothing never reach Ward", async () => {
    const { control, invocations } = await pre("read_files", { files: [{ path: "openspec/specs/auth/spec.md" }] });
    expect([control, invocations.length]).toEqual([undefined, 0]);
  });

  test("a failing check after an edit is appended to the tool result", async () => {
    writeFileSync(join(fixture.root, "FAIL"), "");
    try {
      const { control, invocations } = await post("editor", { path: "src/main/java/A.java", new_text: "x" });
      expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "cline", "--event-stdin"]]);
      expect(control?.context).toContain("Ward quality findings");
    } finally {
      rmSync(join(fixture.root, "FAIL"), { force: true });
    }
  });

  test("a clean edit is silent, and non-editing tools run no check", async () => {
    expect((await post("editor", { path: "src/main/java/A.java" })).control).toBeUndefined();
    expect((await post("run_commands", { commands: '["ls"]' })).invocations.length).toBe(0);
  });

  test("with the guard disabled, the PreToolUse hook allows without running Ward", async () => {
    const file = discovered(join(unguarded.root, ".cline/hooks")).PreToolUse;
    const { control, invocations } = await launch(file, unguarded, {
      ...base(unguarded, "tool_call"),
      preToolUse: { toolName: "run_commands", parameters: { commands: '["rm openspec/specs/auth/spec.md"]' } },
    });
    expect([control, invocations.length]).toEqual([undefined, 0]);
  });
});
